import pygame

pygame.init()
screen = pygame.display.set_mode((800, 600))

background = (0, 0, 0)

while True:
    events = pygame.event.get()
    for event in events:
        if event.type == pygame.QUIT:
            exit()
        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_r:
                background = (255, 0, 0)

    screen.fill(background)
    pygame.display.update()

import pygame

pygame.init()
screen = pygame.display.set_mode((800, 600))

background = (0, 0, 0)

while True:
    events = pygame.event.get()
    for event in events:
        if event.type == pygame.QUIT:
            exit()
        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_r:
                background = (255, 0, 0)
            elif event.key == pygame.K_g:
                background = (0, 255, 0)
            elif event.key == pygame.K_b:
                background = (0, 0, 255)
            elif event.key == pygame.K_SPACE:
                background = (0, 0, 0)

    screen.fill(background)
    pygame.display.update()

import pygame

pygame.init()
screen = pygame.display.set_mode((800, 600))

x = 400

while True:
    events = pygame.event.get()
    for event in events:
        if event.type == pygame.QUIT:
            exit()
        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_RIGHT:
                x += 20

    screen.fill((0, 0, 0))
    pygame.draw.circle(screen, (0, 255, 0), (x, 300), 20)
    pygame.display.update()

